test5.source:
pub fn test5() {
    let mut a = U { f: 6, g: 1, };
    let x = &mut a;
    let y = &mut x.f;
    let z = &mut x.g;
    *y = 7;
    let y2 = &mut *y;
    let z2 = &mut *z;
    *y2 = 3;
    *z2 = 4;
    assert!(a.f == 3);
    assert!(a.g == 4);
    check_u(a);
}

